417			}
418			const floor = byId.get(first.baseExpectedHead.generationId);
419			if (floor === undefined) corrupt("retained rollback lineage contained a gap");
420			if (first.generationId !== firstId || floor.generationId !== floorId) {
421				retry("planned rollback generations changed before reclamation");
422			}
423			if (
424				first.state !== "Superseded" ||
425				floor.state !== "Superseded" ||
426				!parentMatches(active, first, input.expectedHead.revision) ||
427				!parentMatches(first, floor, active.baseExpectedHead.revision)
428			) {
429				corrupt("retained rollback lineage was invalid");
430			}
431	
432			const retained = new Set([active.generationId, first.generationId, floor.generationId]);
433			const selected: GenerationRecord[] = [];
434			let replay = false;
435			let normalizedThisCall = false;
436			if (headsEqual(floor.baseExpectedHead, input.lineageFloor.expectedBaseExpectedHead)) {
437				normalizedThisCall = !headsEqual(
438					input.lineageFloor.expectedBaseExpectedHead,
439					input.lineageFloor.replacementBaseExpectedHead
440				);
441				let cursor = floor.baseExpectedHead;
442				let expectedRevision = first.baseExpectedHead.kind === "present" ? first.baseExpectedHead.revision : 0;
443				const visited = new Set<GenerationId>();
444				while (cursor.kind === "present") {
445					if (visited.has(cursor.generationId)) corrupt("reclamation prefix contained a cycle");
446					const generation = byId.get(cursor.generationId);
447					if (
448						generation === undefined ||
449						generation.state !== "Superseded" ||
450						cursor.objectId !== input.objectId ||
451						cursor.closureDigest !== generation.closureDigest ||
452						cursor.revision !== expectedRevision - 1
453					) {
454						corrupt("reclamation prefix contained a gap or invalid parent");
455					}
456					visited.add(generation.generationId);
457					selected.push(generation);
458					expectedRevision = cursor.revision;
459					cursor = generation.baseExpectedHead;
460				}
461				if (cursor.objectId !== input.objectId) corrupt("reclamation prefix terminated in another object");
462			} else if (headsEqual(floor.baseExpectedHead, input.lineageFloor.replacementBaseExpectedHead)) {
463				replay = true;
464				if (input.lineageFloor.deleteGenerationIds.some((generationId) => byId.has(generationId))) {
465					corrupt("normalized floor retained part of the requested prefix");
466				}
467			} else {
468				retry("lineage floor changed before reclamation");
469			}
470	
471			const selectedIds = selected.map(({ generationId }) => generationId).sort();
472			if (!replay && !sameIds(selectedIds, input.lineageFloor.deleteGenerationIds)) {
473				retry("requested generation prefix no longer matches the complete lineage");
474			}
475			const extras = target.filter(
476				({ generationId }) => !retained.has(generationId) && !selectedIds.includes(generationId)
477			);
478			if (extras.length !== 0) {
479				const requestedPrefix = new Set(input.lineageFloor.deleteGenerationIds);
480				if (
481					replay &&
482					extras.some(
483						({ baseExpectedHead }) =>
484							baseExpectedHead.kind === "present" && requestedPrefix.has(baseExpectedHead.generationId)
485					)
486				) {
487					corrupt("normalized replay retained a dangling parent into the reclaimed prefix");
488				}
489				retry("target generation set changed before reclamation");
490			}
491	
492			const selectedSet = new Set(selectedIds);
493			const deletePromotions = promotions.filter(
494				({ generationId, objectId }) => objectId === input.objectId && selectedSet.has(generationId)
495			);
496			const candidateDigests = new Set(deletePromotions.map(({ digest }) => digest));
497			const remainingGenerationReferences = new Set(
498				generations
499					.filter(({ generationId, objectId }) => objectId !== input.objectId || !selectedSet.has(generationId))
500					.flatMap(({ closure }) => closure.map(({ digest }) => digest))
501			);
502			const remainingPromotionReferences = new Set(
503				promotions
504					.filter(({ generationId, objectId }) => objectId !== input.objectId || !selectedSet.has(generationId))
505					.map(({ digest }) => digest)
506			);
507			const deleteBlobDigests = [...candidateDigests]
508				.filter((digest) => !remainingGenerationReferences.has(digest) && !remainingPromotionReferences.has(digest))
509				.sort();
510			const rewrittenGeneration = cloneGeneration({
511				...floor,
512				baseExpectedHead: input.lineageFloor.replacementBaseExpectedHead,
513			});
514			return Object.freeze({
515				deleteBlobDigests: Object.freeze(deleteBlobDigests),
516				deleteGenerationIds: Object.freeze(normalizedThisCall ? selectedIds : []),
517				deletePromotions: Object.freeze(normalizedThisCall ? deletePromotions : []),
518				floor: Object.freeze({
519					generation: cloneGeneration(floor),
520					normalizedThisCall,
521					rewrittenGeneration,
522				}),
523				input,
524			});
525		} catch (error) {
526			if (error instanceof AheReclamationError) throw error;
527			throw failure("AHE_RECLAMATION_CORRUPT", "native snapshot could not be inspected", error);
528		}
529	}
