116			this.code = code;
117			Object.defineProperty(this, "name", { configurable: true, value: "AheReclamationError" });
118		}
119	}
120	
121	function failure(code: AheReclamationErrorCode, message: string, cause?: unknown): AheReclamationError {
122		return Object.freeze(new AheReclamationError(code, message, cause === undefined ? undefined : { cause }));
123	}
124	
125	function invalid(message: string): never {
126		throw failure("AHE_RECLAMATION_INVALID_ARGUMENT", message);
127	}
128	
129	function retry(message: string): never {
130		throw failure("AHE_RECLAMATION_RETRY_REQUIRED", message);
131	}
132	
133	function corrupt(message: string): never {
134		throw failure("AHE_RECLAMATION_CORRUPT", message);
135	}
136	
137	function cloneHead(head: ExpectedHead): ExpectedHead {
138		return Object.freeze({ ...head });
139	}
140	
141	function cloneGeneration(generation: GenerationRecord): GenerationRecord {
142		return Object.freeze({
143			...generation,
144			baseExpectedHead: cloneHead(generation.baseExpectedHead),
145			closure: Object.freeze(generation.closure.map((reference) => Object.freeze({ ...reference }))),
146		});
147	}
148	
149	function copyGenerationIds(value: unknown): readonly GenerationId[] {
150		if (!isClosedArray(value)) invalid("deleteGenerationIds must be one exact dense array");
151		const ids: GenerationId[] = [];
152		for (const candidate of value) {
153			if (!isGenerationId(candidate)) invalid("deleteGenerationIds must contain canonical generation IDs");
154			ids.push(candidate);
155		}
156		if (new Set(ids).size !== ids.length || ids.some((id, index) => index > 0 && id <= (ids[index - 1] ?? id))) {
157			invalid("deleteGenerationIds must be unique and canonically ordered");
158		}
159		return Object.freeze(ids);
160	}
161	
162	function copyRollbackIds(value: unknown): readonly [GenerationId, GenerationId] {
163		if (!isClosedArray(value) || value.length !== 2 || !isGenerationId(value[0]) || !isGenerationId(value[1])) {
164			invalid("rollbackGenerationIds must contain exactly two canonical IDs");
165		}
166		if (value[0] === value[1]) invalid("rollbackGenerationIds must be distinct");
167		return Object.freeze([value[0], value[1]] as const);
168	}
169	
170	/**
171	 * Validates, detaches, and deeply freezes the AHE subset emitted by D.109a.
172	 * @param value - Untrusted reclamation request.
173	 * @returns Exact captured maintenance input.
174	 */
175	export function captureAheReclamationInput(value: unknown): AheReclamationInput {
176		try {
177			if (
178				!isClosedRecord(value, [
179					"activeGenerationId",
180					"availabilityPolicyDigest",
181					"closedEpoch",
182					"expectedHead",
183					"lineageFloor",
184					"objectId",
185					"rollbackGenerationIds",
186				]) ||
187				!isStorageObjectId(value.objectId) ||
188				!isGenerationId(value.activeGenerationId) ||
189				value.availabilityPolicyDigest !== AHE_RECLAMATION_LOCAL_ONLY_POLICY_DIGEST ||
190				!Number.isSafeInteger(value.closedEpoch) ||
191				Number(value.closedEpoch) < 0 ||
192				!isClosedRecord(value.lineageFloor, [
193					"deleteGenerationIds",
194					"expectedBaseExpectedHead",
195					"generationId",
196					"replacementBaseExpectedHead",
197				]) ||
198				!isGenerationId(value.lineageFloor.generationId)
199			) {
200				invalid("reclamation input must be one exact validated record");
201			}
202			const expectedHead = copyExpectedHead(value.expectedHead, value.objectId);
203			const expectedBaseExpectedHead = copyExpectedHead(value.lineageFloor.expectedBaseExpectedHead, value.objectId);
204			const replacementBaseExpectedHead = copyExpectedHead(
205				value.lineageFloor.replacementBaseExpectedHead,
206				value.objectId
207			);
208			if (
209				expectedHead?.kind !== "present" ||
210				expectedHead.generationId !== value.activeGenerationId ||
211				expectedBaseExpectedHead === undefined ||
212				replacementBaseExpectedHead?.kind !== "none"
213			) {
214				invalid("reclamation input identities must agree");
215			}
216			const rollbackGenerationIds = copyRollbackIds(value.rollbackGenerationIds);
217			const deleteGenerationIds = copyGenerationIds(value.lineageFloor.deleteGenerationIds);
218			const retained = new Set<GenerationId>([
219				value.activeGenerationId,
220				rollbackGenerationIds[0],
221				rollbackGenerationIds[1],
222			]);
223			if (
224				retained.size !== 3 ||
225				value.lineageFloor.generationId !== rollbackGenerationIds[1] ||
226				deleteGenerationIds.some((generationId) => retained.has(generationId))
227			) {
228				invalid("reclamation input generations must be disjoint and floor-bound");
229			}
230			return Object.freeze({
231				activeGenerationId: value.activeGenerationId,
232				availabilityPolicyDigest: value.availabilityPolicyDigest,
233				closedEpoch: Number(value.closedEpoch),
234				expectedHead: cloneHead(expectedHead) as PresentHead,
235				lineageFloor: Object.freeze({
236					deleteGenerationIds,
237					expectedBaseExpectedHead: cloneHead(expectedBaseExpectedHead),
238					generationId: value.lineageFloor.generationId,
239					replacementBaseExpectedHead: cloneHead(replacementBaseExpectedHead) as Readonly<{
240						kind: "none";
241						objectId: StorageObjectId;
242					}>,
243				}),
244				objectId: value.objectId,
245				rollbackGenerationIds,
246			});
247		} catch (error) {
248			if (error instanceof AheReclamationError) throw error;
249			throw failure("AHE_RECLAMATION_INVALID_ARGUMENT", "reclamation input could not be inspected", error);
250		}
251	}
252	
253	function generationKey(objectId: StorageObjectId, generationId: GenerationId): string {
254		return `${objectId}\0${generationId}`;
255	}
256	
257	function promotionKey(promotion: AheReclamationPromotion): string {
258		return `${promotion.objectId}\0${promotion.generationId}\0${promotion.digest}`;
259	}
260	
261	function copyPromotions(value: unknown): readonly AheReclamationPromotion[] {
262		if (!isClosedArray(value)) corrupt("promotion scan was not a dense array");
263		const promotions: AheReclamationPromotion[] = [];
264		const keys = new Set<string>();
265		for (const candidate of value) {
266			if (
267				!isClosedRecord(candidate, ["digest", "generationId", "objectId"]) ||
268				!isStorageObjectId(candidate.objectId) ||
269				!isGenerationId(candidate.generationId) ||
270				!isBlobDigest(candidate.digest)
271			) {
272				corrupt("promotion scan contained a malformed row");
273			}
274			const promotion = Object.freeze({
275				digest: candidate.digest,
276				generationId: candidate.generationId,
277				objectId: candidate.objectId,
278			});
279			const key = promotionKey(promotion);
280			if (keys.has(key)) corrupt("promotion scan contained a duplicate row");
281			keys.add(key);
282			promotions.push(promotion);
283		}
284		return Object.freeze(promotions);
285	}
286	
287	function copyGenerations(value: unknown): readonly GenerationRecord[] {
288		if (!isClosedArray(value)) corrupt("generation scan was not a dense array");
289		const generations: GenerationRecord[] = [];
290		const keys = new Set<string>();
291		for (const candidate of value) {
292			const generation = copyGenerationRecord(candidate);
293			if (generation === undefined) corrupt("generation scan contained a malformed row");
294			const key = generationKey(generation.objectId, generation.generationId);
295			if (keys.has(key)) corrupt("generation scan contained a duplicate identity");
296			keys.add(key);
297			const recomputed = digestClosure(generation.closure);
298			if (!recomputed.ok || recomputed.value !== generation.closureDigest) {
299				corrupt("generation scan contained an invalid closure digest");
300			}
301			generations.push(cloneGeneration(generation));
302		}
303		return Object.freeze(generations);
304	}
305	
306	function copyBlobFacts(value: unknown): ReadonlyMap<BlobDigest, Readonly<{ byteLength: number; valid: boolean }>> {
307		if (!isClosedArray(value)) corrupt("blob observation scan was not a dense array");
308		const blobs = new Map<BlobDigest, Readonly<{ byteLength: number; valid: boolean }>>();
309		for (const candidate of value) {
310			if (
311				!isClosedRecord(candidate, ["bytes", "digest"]) ||
312				!isBlobDigest(candidate.digest) ||
313				!(candidate.bytes instanceof Uint8Array) ||
314				hasSharedBacking(candidate.bytes) ||
315				blobs.has(candidate.digest)
316			) {
317				corrupt("blob observation scan contained a malformed or duplicate row");
318			}
319			const recomputed = digestBlob(candidate.bytes);
320			blobs.set(
321				candidate.digest,
322				Object.freeze({
323					byteLength: candidate.bytes.byteLength,
324					valid: recomputed.ok && recomputed.value === candidate.digest,
325				})
326			);
327		}
328		return blobs;
329	}
330	
331	function verifyPromotionsAndBlobs(
332		generations: readonly GenerationRecord[],
333		promotions: readonly AheReclamationPromotion[],
334		blobs: ReadonlyMap<BlobDigest, Readonly<{ byteLength: number; valid: boolean }>>
335	): void {
336		const byGeneration = new Map<string, Set<BlobDigest>>();
337		const records = new Map(
338			generations.map((generation) => [generationKey(generation.objectId, generation.generationId), generation])
339		);
340		for (const promotion of promotions) {
341			const key = generationKey(promotion.objectId, promotion.generationId);
342			const generation = records.get(key);
343			const reference = generation?.closure.find(({ digest }) => digest === promotion.digest);
344			if (generation === undefined || reference === undefined)
345				corrupt("promotion did not belong to its generation closure");
346			const blob = blobs.get(promotion.digest);
347			if (blob === undefined || !blob.valid || blob.byteLength !== reference.byteLength) {
348				corrupt("promoted blob was missing, corrupt, or had the wrong length");
349			}
350			const observed = byGeneration.get(key) ?? new Set<BlobDigest>();
351			observed.add(promotion.digest);
352			byGeneration.set(key, observed);
353		}
354		for (const generation of generations) {
355			const observed = byGeneration.get(generationKey(generation.objectId, generation.generationId)) ?? new Set();
356			const required =
357				generation.state === "Complete" || generation.state === "Adopted" || generation.state === "Superseded";
358			if (
359				required &&
360				(observed.size !== generation.closure.length || generation.closure.some(({ digest }) => !observed.has(digest)))
361			) {
362				corrupt("complete generation did not have its exact promotion set");
363			}
364		}
365	}
366	
367	function parentMatches(child: GenerationRecord, parent: GenerationRecord, childRevision: number): boolean {
368		return (
369			child.baseExpectedHead.kind === "present" &&
370			child.baseExpectedHead.objectId === parent.objectId &&
371			child.baseExpectedHead.generationId === parent.generationId &&
372			child.baseExpectedHead.closureDigest === parent.closureDigest &&
373			child.baseExpectedHead.revision === childRevision - 1
374		);
375	}
376	
377	function sameIds(left: readonly GenerationId[], right: readonly GenerationId[]): boolean {
378		return left.length === right.length && left.every((value, index) => value === right[index]);
379	}
380	
381	/**
382	 * Produces the one pure deletion decision consumed inside native transactions.
383	 * @param request - Untrusted D.109a AHE subset.
384	 * @param snapshot - Complete decoded generation/promotion scan plus required blob observations.
385	 * @returns Frozen floor rewrite and exact physical deletion set.
386	 */
387	export function classifyAheReclamation(request: unknown, snapshot: AheReclamationSnapshot): AheReclamationDecision {
388		const input = captureAheReclamationInput(request);
389		try {
390			if (!isClosedRecord(snapshot, ["blobs", "generations", "head", "promotions"])) {
391				corrupt("native snapshot was not one exact record");
392			}
393			const head = copyExpectedHead(snapshot.head, input.objectId);
394			if (head === undefined) corrupt("native head was malformed or cross-object");
395			if (!headsEqual(head, input.expectedHead)) retry("head changed before reclamation");
396			const generations = copyGenerations(snapshot.generations);
397			const promotions = copyPromotions(snapshot.promotions);
398			const blobs = copyBlobFacts(snapshot.blobs);
399			verifyPromotionsAndBlobs(generations, promotions, blobs);
400	
401			const target = generations.filter(({ objectId }) => objectId === input.objectId);
402			const byId = new Map(target.map((generation) => [generation.generationId, generation]));
403			const active = byId.get(input.activeGenerationId);
404			if (
405				active === undefined ||
406				active.state !== "Adopted" ||
407				active.closureDigest !== input.expectedHead.closureDigest
408			) {
409				corrupt("active head did not bind one adopted generation");
410			}
411			const firstId = input.rollbackGenerationIds[0];
412			const floorId = input.rollbackGenerationIds[1];
413			if (active.baseExpectedHead.kind !== "present") corrupt("active generation did not retain a rollback parent");
414			const first = byId.get(active.baseExpectedHead.generationId);
415			if (first === undefined || first.baseExpectedHead.kind !== "present") {
416				corrupt("retained rollback lineage contained a gap");
417			}
418			const floor = byId.get(first.baseExpectedHead.generationId);
419			if (floor === undefined) corrupt("retained rollback lineage contained a gap");
420			if (first.generationId !== firstId || floor.generationId !== floorId) {
421				retry("planned rollback generations changed before reclamation");
422			}
423			if (
424				first.state !== "Superseded" ||
425				floor.state !== "Superseded" ||
426				!parentMatches(active, first, input.expectedHead.revision) ||
427				!parentMatches(first, floor, active.baseExpectedHead.revision)
428			) {
429				corrupt("retained rollback lineage was invalid");
430			}
431	
432			const retained = new Set([active.generationId, first.generationId, floor.generationId]);
433			const selected: GenerationRecord[] = [];
434			let replay = false;
435			let normalizedThisCall = false;
436			if (headsEqual(floor.baseExpectedHead, input.lineageFloor.expectedBaseExpectedHead)) {
437				normalizedThisCall = !headsEqual(
438					input.lineageFloor.expectedBaseExpectedHead,
439					input.lineageFloor.replacementBaseExpectedHead
440				);
441				let cursor = floor.baseExpectedHead;
442				let expectedRevision = first.baseExpectedHead.kind === "present" ? first.baseExpectedHead.revision : 0;
443				const visited = new Set<GenerationId>();
444				while (cursor.kind === "present") {
445					if (visited.has(cursor.generationId)) corrupt("reclamation prefix contained a cycle");
446					const generation = byId.get(cursor.generationId);
447					if (
448						generation === undefined ||
449						generation.state !== "Superseded" ||
450						cursor.objectId !== input.objectId ||
451						cursor.closureDigest !== generation.closureDigest ||
452						cursor.revision !== expectedRevision - 1
453					) {
454						corrupt("reclamation prefix contained a gap or invalid parent");
455					}
456					visited.add(generation.generationId);
457					selected.push(generation);
458					expectedRevision = cursor.revision;
459					cursor = generation.baseExpectedHead;
460				}
461				if (cursor.objectId !== input.objectId) corrupt("reclamation prefix terminated in another object");
462			} else if (headsEqual(floor.baseExpectedHead, input.lineageFloor.replacementBaseExpectedHead)) {
463				replay = true;
464				if (input.lineageFloor.deleteGenerationIds.some((generationId) => byId.has(generationId))) {
465					corrupt("normalized floor retained part of the requested prefix");
466				}
467			} else {
468				retry("lineage floor changed before reclamation");
469			}
470	
471			const selectedIds = selected.map(({ generationId }) => generationId).sort();
472			if (!replay && !sameIds(selectedIds, input.lineageFloor.deleteGenerationIds)) {
473				retry("requested generation prefix no longer matches the complete lineage");
474			}
475			const extras = target.filter(
476				({ generationId }) => !retained.has(generationId) && !selectedIds.includes(generationId)
477			);
478			if (extras.length !== 0) {
479				const requestedPrefix = new Set(input.lineageFloor.deleteGenerationIds);
480				if (
481					replay &&
482					extras.some(
483						({ baseExpectedHead }) =>
484							baseExpectedHead.kind === "present" && requestedPrefix.has(baseExpectedHead.generationId)
485					)
486				) {
487					corrupt("normalized replay retained a dangling parent into the reclaimed prefix");
488				}
489				retry("target generation set changed before reclamation");
490			}
491	
492			const selectedSet = new Set(selectedIds);
493			const deletePromotions = promotions.filter(
494				({ generationId, objectId }) => objectId === input.objectId && selectedSet.has(generationId)
495			);
496			const candidateDigests = new Set(deletePromotions.map(({ digest }) => digest));
497			const remainingGenerationReferences = new Set(
498				generations
499					.filter(({ generationId, objectId }) => objectId !== input.objectId || !selectedSet.has(generationId))
500					.flatMap(({ closure }) => closure.map(({ digest }) => digest))
501			);
502			const remainingPromotionReferences = new Set(
503				promotions
504					.filter(({ generationId, objectId }) => objectId !== input.objectId || !selectedSet.has(generationId))
505					.map(({ digest }) => digest)
506			);
507			const deleteBlobDigests = [...candidateDigests]
508				.filter((digest) => !remainingGenerationReferences.has(digest) && !remainingPromotionReferences.has(digest))
509				.sort();
510			const rewrittenGeneration = cloneGeneration({
511				...floor,
512				baseExpectedHead: input.lineageFloor.replacementBaseExpectedHead,
513			});
514			return Object.freeze({
515				deleteBlobDigests: Object.freeze(deleteBlobDigests),
516				deleteGenerationIds: Object.freeze(normalizedThisCall ? selectedIds : []),
517				deletePromotions: Object.freeze(normalizedThisCall ? deletePromotions : []),
518				floor: Object.freeze({
519					generation: cloneGeneration(floor),
520					normalizedThisCall,
521					rewrittenGeneration,
522				}),
523				input,
524			});
525		} catch (error) {
526			if (error instanceof AheReclamationError) throw error;
527			throw failure("AHE_RECLAMATION_CORRUPT", "native snapshot could not be inspected", error);
528		}
529	}
530	
531	/**
532	 * Constructs the detached immutable receipt after exact native row counts pass.
533	 * @param decision - Shared classifier decision used by the transaction.
534	 * @returns Frozen receipt containing actual writes for this call.
535	 */
536	export function createAheReclamationReceipt(decision: AheReclamationDecision): AheReclamationReceipt {
537		const { input } = decision;
538		return Object.freeze({
539			activeGenerationId: input.activeGenerationId,
540			availabilityPolicyDigest: input.availabilityPolicyDigest,
541			closedEpoch: input.closedEpoch,
542			deletedBlobDigests: Object.freeze([...decision.deleteBlobDigests]),
543			deletedGenerationIds: Object.freeze([...decision.deleteGenerationIds]),
544			deletedPromotionCount: decision.deletePromotions.length,
545			expectedHead: cloneHead(input.expectedHead) as PresentHead,
546			floor: Object.freeze({
547				expectedFormerBaseExpectedHead: cloneHead(input.lineageFloor.expectedBaseExpectedHead),
548				generationId: input.lineageFloor.generationId,
549				normalizedThisCall: decision.floor.normalizedThisCall,
550				replacementBaseExpectedHead: cloneHead(input.lineageFloor.replacementBaseExpectedHead) as Readonly<{
551					kind: "none";
552					objectId: StorageObjectId;
553				}>,
554			}),
555			objectId: input.objectId,
556			reclaimedGenerationIds: Object.freeze([...input.lineageFloor.deleteGenerationIds]),
557			rollbackGenerationIds: Object.freeze([...input.rollbackGenerationIds]) as readonly [GenerationId, GenerationId],
558		});
559	}
560	
561	/**
562	 * Creates one frozen lifecycle or substrate error without widening the code set.
563	 * @param code - Closed error code.
564	 * @param message - Diagnostic summary.
565	 * @param cause - Optional substrate cause.
566	 * @returns Frozen classified error.
567	 */
568	export function createAheReclamationError(
569		code: AheReclamationErrorCode,
570		message: string,
571		cause?: unknown
572	): AheReclamationError {
573		return failure(code, message, cause);
574	}

