 29	function readiness(): Readonly<{ readonly missing: readonly string[]; readonly ready: boolean }> {
 30		const missing = !existsSync(resolve(REPOSITORY_ROOT, SHARED_OWNER))
 31			? [SHARED_OWNER]
 32			: source(SHARED_OWNER).includes("AHE_RECLAMATION_ERROR_CODES")
 33				? []
