 53			expect(D109C_REFERENCE_CASES).toHaveLength(6);
 54			expect(D109C_COUNT_MUTANTS).toHaveLength(4);
 55			expect(D109C_CRASH_EDGES).toEqual([
 56				"after-floor-rewrite",
 57				"after-promotion-delete",
 58				"after-generation-delete",
 59				"after-blob-delete",
 60				"before-commit",
 61				"after-commit",
 62			]);
 63		});
 64	
 65		it("pins the unchanged 12-key facade, ephemeral memory owner and D.109a lineage predicates", () => {
 66			const memory = source("packages/storage/src/memory.ts");
 67			const transition = source("packages/storage/src/internal/transition.ts");
 68			const planner = source("packages/node/src/internal/closed-epoch-cleanup.ts");
 69			const adoption = source("packages/node/src/creator-adoption.ts");
 70			const adoptionCommit = source("packages/node/src/creator-adoption-commit.ts");
 71			expect(memory).toContain('new TransitionOwner("ephemeral")');
 72			expect(memory).not.toContain("resolveMemoryAheReclamationMaintenance");
 73			expect(transition).toContain('if (this.durability === "ephemeral") return rejected("DURABILITY_UNAVAILABLE")');
 74			expect(transition).not.toContain("reclaimClosedEpoch");
 75			expect(planner).toContain("cursor.revision !== expectedRevision - 1");
 76			expect(planner).toContain("child.baseExpectedHead.revision === expectedChildRevision - 1");
 77			expect(adoption).toContain("!byId.has(generation.baseExpectedHead.generationId)");
 78			expect(adoptionCommit).toContain("!byId.has(generation.baseExpectedHead.generationId)");
 79		});
 80	
 81		it("freezes the current storage export map before the additive maintenance subpath", () => {
