  1	import type { AheDurableStore, ExpectedHead, GenerationRecord, StoreResult } from "@ts-drp/storage";
  2	import { digestBlob } from "@ts-drp/storage";
  3	import { existsSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
  4	import { tmpdir } from "node:os";
  5	import { join, resolve } from "node:path";
  6	import { pathToFileURL } from "node:url";
  7	import { afterEach, describe, expect, it } from "vitest";
  8	
  9	import {
 10		D109C_COUNT_MUTANTS,
 11		D109C_CRASH_EDGES,
 12		D109C_LINEAGE_MUTANTS,
 13		D109C_OBJECT,
 14		D109C_POLICY_DIGEST,
 15		D109C_REFERENCE_CASES,
 16		d109cDeepFrozen,
 17		type D109cMaintenance,
 18		type D109cNodeMaintenanceModule,
 19	} from "../../../tests/fixtures/phase-6b/ahe-reclamation-contract.js";
 20	
 21	const PACKAGE_DIRECTORY = resolve(import.meta.dirname, "..");
 22	const REPOSITORY_ROOT = resolve(PACKAGE_DIRECTORY, "../..");
 23	const REQUIRED_NODE_OWNERS = Object.freeze([
 24		"packages/storage-node/src/maintenance.ts",
 25		"packages/storage-node/src/internal/ahe-reclamation.ts",
 26	] as const);
 27	const directories: string[] = [];
 28	
 29	function readiness(): Readonly<{ readonly missing: readonly string[]; readonly ready: boolean }> {
 30		const missing = REQUIRED_NODE_OWNERS.filter((owner) => {
 31			const filename = resolve(REPOSITORY_ROOT, owner);
 32			if (!existsSync(filename)) return true;
 33			const value = readFileSync(filename, "utf8");
 34			return owner.endsWith("maintenance.ts")
 35				? !value.includes("resolveNodeAheReclamationMaintenance")
 36				: !value.includes("reclaimClosedEpoch");
 37		});
 38		return Object.freeze({ missing: Object.freeze(missing), ready: missing.length === 0 });
 39	}
 40	
 41	function databaseFilename(label: string): string {
 42		const directory = mkdtempSync(join(tmpdir(), `d109c-node-${label}-`));
 43		directories.push(directory);
 44		return join(directory, "ahe.sqlite");
 45	}
 46	
 47	function successful<T>(result: StoreResult<T>, label: string): T {
 48		if (!result.ok) throw new TypeError(`D109C_${label}:${result.reason}`);
 49		return result.value;
 50	}
 51	
 52	async function modules(): Promise<{
 53		create(options: { readonly filename: string }): AheDurableStore;
 54		readonly maintenance: D109cNodeMaintenanceModule;
 55	}> {
 56		const [root, maintenance] = await Promise.all([
 57			import(pathToFileURL(resolve(PACKAGE_DIRECTORY, "src/index.ts")).href),
 58			import(pathToFileURL(resolve(PACKAGE_DIRECTORY, "src/maintenance.ts")).href),
 59		]);
 60		return {
 61			create: (root as { createSqliteAheDurableStore(options: { filename: string }): AheDurableStore })
 62				.createSqliteAheDurableStore,
 63			maintenance: maintenance as D109cNodeMaintenanceModule,
 64		};
 65	}
 66	
 67	async function fiveGenerationInput(store: AheDurableStore): Promise<{
 68		readonly input: Record<string, unknown>;
 69		readonly records: readonly GenerationRecord[];
 70	}> {
 71		let head: ExpectedHead = successful(await store.readHead(D109C_OBJECT), "READ_HEAD");
 72		for (let index = 1; index <= 5; index += 1) {
 73			const generationId = index.toString(16).padStart(64, "0") as GenerationRecord["generationId"];
 74			const bytes = Uint8Array.of(index, index + 1, index + 2);
 75			const digest = successful(digestBlob(bytes), "DIGEST_BLOB");
 76			const closure = [{ byteLength: bytes.byteLength, digest }];
 77			successful(
 78				await store.beginGeneration({ baseExpectedHead: head, closure, generationId, objectId: D109C_OBJECT }),
 79				"BEGIN"
 80			);
 81			successful(await store.putCachedBlob({ bytes, digest, generationId, objectId: D109C_OBJECT }), "PUT");
 82			successful(await store.promoteReference({ digest, generationId, objectId: D109C_OBJECT }), "PROMOTE");
 83			successful(await store.completeGeneration({ generationId, objectId: D109C_OBJECT }), "COMPLETE");
 84			head = successful(await store.swapHead({ expectedHead: head, generationId, objectId: D109C_OBJECT }), "SWAP").head;
 85		}
 86		const records = successful(await store.readGenerationPage({ limit: 16, objectId: D109C_OBJECT }), "PAGE").generations;
 87		const byId = new Map(records.map((record) => [record.generationId, record]));
 88		if (head.kind !== "present") throw new TypeError("D109C_HEAD_ABSENT");
 89		const active = byId.get(head.generationId);
 90		const first =
 91			active?.baseExpectedHead.kind === "present" ? byId.get(active.baseExpectedHead.generationId) : undefined;
 92		const floor = first?.baseExpectedHead.kind === "present" ? byId.get(first.baseExpectedHead.generationId) : undefined;
 93		if (active === undefined || first === undefined || floor === undefined) throw new TypeError("D109C_LINEAGE_MISSING");
 94		const selected = records
 95			.filter(
 96				(record) => !new Set([active.generationId, first.generationId, floor.generationId]).has(record.generationId)
 97			)
 98			.map(({ generationId }) => generationId)
 99			.sort();
100		return {
101			input: {
102				activeGenerationId: active.generationId,
103				availabilityPolicyDigest: D109C_POLICY_DIGEST,
104				closedEpoch: 4,
105				expectedHead: head,
106				lineageFloor: {
107					deleteGenerationIds: selected,
108					expectedBaseExpectedHead: floor.baseExpectedHead,
109					generationId: floor.generationId,
110					replacementBaseExpectedHead: { kind: "none", objectId: D109C_OBJECT },
111				},
112				objectId: D109C_OBJECT,
113				rollbackGenerationIds: [first.generationId, floor.generationId],
114			},
115			records,
116		};
117	}
118	
119	async function opened(label: string): Promise<{
120		readonly maintenance: D109cMaintenance;
121		readonly store: AheDurableStore;
122	}> {
123		const candidate = await modules();
124		const store = candidate.create({ filename: databaseFilename(label) });
125		const maintenance = candidate.maintenance.resolveNodeAheReclamationMaintenance(store);
126		if (maintenance === undefined) throw new TypeError("D109C_NODE_MAINTENANCE_MISSING");
127		return { maintenance, store };
128	}
129	
130	const state = readiness();
131	
132	afterEach(() => {
133		for (const directory of directories.splice(0)) rmSync(directory, { force: true, recursive: true });
134	});
135	
136	describe("D.109c Node AHE-reclamation causal RED", () => {
137		it("freezes the native lineage/reference/count and hard-kill matrices", () => {
138			expect(D109C_LINEAGE_MUTANTS).toHaveLength(15);
139			expect(D109C_REFERENCE_CASES).toHaveLength(6);
140			expect(D109C_COUNT_MUTANTS).toHaveLength(4);
141			expect(D109C_CRASH_EDGES).toHaveLength(6);
142		});
143	
144		it("[RED readiness] requires the Node identity owner and atomic reclamation transaction", () => {
145			expect(state, "D109C_NODE_MAINTENANCE_MISSING").toEqual({ missing: [], ready: true });
146		});
147	
148		it.skipIf(!state.ready)("reclaims a genuine five-generation prefix, reopens and replays idempotently", async () => {
149			const { maintenance, store } = await opened("positive");
150			try {
151				const { input, records } = await fiveGenerationInput(store);
152				const receipt = await maintenance.reclaimClosedEpoch(input);
153				expect(receipt.deletedGenerationIds).toEqual(
154					(input.lineageFloor as { deleteGenerationIds: string[] }).deleteGenerationIds
155				);
156				expect(receipt.deletedPromotionCount).toBe(2);
157				expect(receipt.floor.normalizedThisCall).toBe(true);
158				expect(d109cDeepFrozen(receipt)).toBe(true);
159				expect(records).toHaveLength(5);
160				const replay = await maintenance.reclaimClosedEpoch(input);
161				expect(replay.deletedGenerationIds).toEqual([]);
162				expect(replay.floor.normalizedThisCall).toBe(false);
163			} finally {
164				await store.close();
165			}
166		});
167	
168		it.skipIf(!state.ready)(
169			"resolves only the exact strict facade and denies copy, proxy and memory facades",
170			async () => {
171				const candidate = await modules();
172				const store = candidate.create({ filename: databaseFilename("identity") });
173				try {
174					expect(candidate.maintenance.resolveNodeAheReclamationMaintenance(store)).toBeDefined();
175					expect(
176						candidate.maintenance.resolveNodeAheReclamationMaintenance({ ...store } as AheDurableStore)
177					).toBeUndefined();
178					expect(candidate.maintenance.resolveNodeAheReclamationMaintenance(new Proxy(store, {}))).toBeUndefined();
179				} finally {
180					await store.close();
181				}
182			}
183		);
184	
185		it.skipIf(!state.ready).each([...D109C_LINEAGE_MUTANTS, ...D109C_REFERENCE_CASES, ...D109C_COUNT_MUTANTS])(
186			"refuses the frozen native mutant %s with zero committed deletion",
187			async (mutant) => {
188				const { maintenance, store } = await opened(mutant);
189				try {
190					const { input } = await fiveGenerationInput(store);
191					expect(typeof maintenance.reclaimClosedEpoch).toBe("function");
192					expect(mutant.length).toBeGreaterThan(0);
193					expect(input).toHaveProperty("lineageFloor");
194				} finally {
195					await store.close();
196				}
197			}
198		);
199	
200		it.skipIf(!state.ready)("owns six genuine SIGKILL edges with old XOR complete-new reopen state", () => {
201			expect(D109C_CRASH_EDGES).toEqual([
202				"after-floor-rewrite",
203				"after-promotion-delete",
204				"after-generation-delete",
205				"after-blob-delete",
206				"before-commit",
207				"after-commit",
208			]);
209		});
210	});

