170	function normalized(value: unknown): unknown {
171		if (value instanceof Uint8Array) return Buffer.from(value).toString("hex");
172		if (typeof value === "bigint") return value.toString();
173		if (Array.isArray(value)) return value.map(normalized);
174		if (typeof value === "object" && value !== null) {
175			return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, normalized(item)]));
176		}
177		return value;
178	}
