200			.get(D109C_OBJECT, generationId) as { readonly record?: unknown } | undefined;
201		if (!(row?.record instanceof Uint8Array)) throw new TypeError("D109C_NATIVE_RECORD_MISSING");
202		const decoded = decodeGenerationRecordV1(row.record);
203		if (decoded.ok === false) throw new TypeError(`D109C_NATIVE_RECORD_INVALID:${decoded.reason}`);
204		return decoded.value;
