223	function applyLineageOrCorruptionMutant(
224		filename: string,
225		input: Record<string, unknown>,
226		mutant: string
227	): Readonly<{ code: string; request: MutableRequest }> {
228		const request = mutableRequest(input);
229		const corruptCode = "AHE_RECLAMATION_CORRUPT";
230		const retryCode = "AHE_RECLAMATION_RETRY_REQUIRED";
231		if (mutant === "head-different") {
232			request.expectedHead.closureDigest = "f".repeat(64);
233			return { code: retryCode, request };
234		}
235		if (mutant === "revision-stale") {
236			request.expectedHead.revision = 4;
237			return { code: retryCode, request };
238		}
239		if (mutant === "active-mismatch") {
240			request.activeGenerationId = d109cGenerationId(4);
241			return { code: "AHE_RECLAMATION_INVALID_ARGUMENT", request };
242		}
243		if (mutant === "rollback-insufficient" || mutant === "rollback-wrong-countable-pair" || mutant === "floor-wrong") {
244			const second = mutant === "rollback-insufficient" ? d109cGenerationId(9) : d109cGenerationId(2);
245			request.rollbackGenerationIds = [
246				mutant === "rollback-wrong-countable-pair" ? d109cGenerationId(3) : d109cGenerationId(4),
247				second,
248			];
249			if (mutant === "rollback-wrong-countable-pair") {
250				request.lineageFloor.deleteGenerationIds = [d109cGenerationId(1), d109cGenerationId(4)];
251			} else if (mutant === "floor-wrong") {
252				request.lineageFloor.deleteGenerationIds = [d109cGenerationId(1), d109cGenerationId(3)];
253			}
254			request.lineageFloor.generationId = second;
255			request.lineageFloor.expectedBaseExpectedHead = d109cNoHead();
256			return { code: retryCode, request };
257		}
258		if (mutant === "former-parent-wrong") {
259			request.lineageFloor.expectedBaseExpectedHead = d109cNoHead();
260			return { code: retryCode, request };
261		}
262		withDatabase(filename, (database) => {
263			const first = generationRecord(database, d109cGenerationId(1));
264			const second = generationRecord(database, d109cGenerationId(2));
265			const active = generationRecord(database, d109cGenerationId(5));
266			if (mutant === "identity-duplicate" || mutant === "generation-key-record-mismatch") {
267				replaceGeneration(database, first.generationId, second);
268			} else if (mutant === "closure-changed") {
269				replaceGeneration(database, active.generationId, {
270					...active,
271					closure: second.closure,
272					closureDigest: second.closureDigest,
273				});
274			} else if (mutant === "state-changed") {
275				replaceGeneration(database, active.generationId, { ...active, state: "Superseded" });
276			} else if (mutant === "lineage-gap") {
277				database
278					.prepare("DELETE FROM promotions WHERE object_id = ? AND generation_id = ?")
279					.run(D109C_OBJECT, first.generationId);
280				database
281					.prepare("DELETE FROM generations WHERE object_id = ? AND generation_id = ?")
282					.run(D109C_OBJECT, first.generationId);
283			} else if (mutant === "lineage-cycle") {
284				replaceGeneration(database, first.generationId, {
285					...first,
286					baseExpectedHead: {
287						closureDigest: second.closureDigest,
288						generationId: second.generationId,
289						kind: "present",
290						objectId: D109C_OBJECT,
291						revision: 2 as PresentHead["revision"],
292					},
293				});
294			} else if (
295				mutant === "surviving-branch" ||
296				mutant === "extra-target-row" ||
297				mutant === "post-state-dangling-parent"
298			) {
299				const generationId = d109cGenerationId(mutant === "extra-target-row" ? 7 : mutant === "surviving-branch" ? 8 : 9);
300				const extra: GenerationRecord = {
301					...first,
302					baseExpectedHead: mutant === "extra-target-row" ? d109cNoHead() : second.baseExpectedHead,
303					generationId,
304					state: "Staged",
305				};
306				database
307					.prepare("INSERT INTO generations(object_id,generation_id,record) VALUES (?,?,?)")
308					.run(D109C_OBJECT, generationId, encodeGenerationRecordV1(extra));
309				if (mutant === "post-state-dangling-parent") {
310					const floor = generationRecord(database, d109cGenerationId(3));
311					replaceGeneration(database, floor.generationId, { ...floor, baseExpectedHead: d109cNoHead() });
312					database
313						.prepare("DELETE FROM promotions WHERE object_id = ? AND generation_id IN (?,?)")
314						.run(D109C_OBJECT, d109cGenerationId(1), d109cGenerationId(2));
315					database
316						.prepare("DELETE FROM generations WHERE object_id = ? AND generation_id IN (?,?)")
317						.run(D109C_OBJECT, d109cGenerationId(1), d109cGenerationId(2));
318				}
319			} else if (mutant === "retained-blob-missing" || mutant === "retained-blob-corrupt") {
320				const digest = active.closure[0]?.digest;
321				if (digest === undefined) throw new TypeError("D109C_NATIVE_DIGEST_MISSING");
322				if (mutant === "retained-blob-missing") {
323					database.exec("PRAGMA foreign_keys=OFF");
324					database.prepare("DELETE FROM blobs WHERE digest = ?").run(digest);
325				} else database.prepare("UPDATE blobs SET bytes = ? WHERE digest = ?").run(Uint8Array.of(0), digest);
326			} else if (mutant === "promotion-missing") {
327				database
328					.prepare("DELETE FROM promotions WHERE object_id = ? AND generation_id = ?")
329					.run(D109C_OBJECT, active.generationId);
330			} else if (mutant === "promotion-extra" || mutant === "promotion-wrong-digest") {
331				const digest = second.closure[0]?.digest;
332				if (digest === undefined) throw new TypeError("D109C_NATIVE_DIGEST_MISSING");
333				database
334					.prepare("INSERT INTO promotions(object_id,generation_id,digest) VALUES (?,?,?)")
335					.run(D109C_OBJECT, active.generationId, digest);
336			} else if (mutant === "target-generation-malformed") {
337				replaceGeneration(database, first.generationId, Uint8Array.of(0));
338			} else if (mutant === "unrelated-generation-malformed") {
339				database.prepare("INSERT INTO objects(object_id,head_record) VALUES (?,NULL)").run(D109C_OTHER_OBJECT);
340				database
341					.prepare("INSERT INTO generations(object_id,generation_id,record) VALUES (?,?,?)")
342					.run(D109C_OTHER_OBJECT, d109cGenerationId(9), Uint8Array.of(0));
343			} else if (mutant === "partial-replay") {
344				const floor = generationRecord(database, d109cGenerationId(3));
345				replaceGeneration(database, floor.generationId, { ...floor, baseExpectedHead: d109cNoHead() });
346				database
347					.prepare("DELETE FROM promotions WHERE object_id = ? AND generation_id = ?")
348					.run(D109C_OBJECT, first.generationId);
349				database
350					.prepare("DELETE FROM generations WHERE object_id = ? AND generation_id = ?")
351					.run(D109C_OBJECT, first.generationId);
352			}
353		});
354		return {
355			code: mutant === "surviving-branch" || mutant === "extra-target-row" ? retryCode : corruptCode,
356			request,
357		};
358	}
