462	async function hardKillAt(filename: string, edge: string): Promise<void> {
463		const childFilename = resolve(PACKAGE_DIRECTORY, "tests/fixtures/phase-6b-ahe-reclamation-child.mjs");
464		await new Promise<void>((resolvePromise, reject) => {
465			const child = fork(childFilename, [filename, edge], {
466				cwd: REPOSITORY_ROOT,
467				execArgv: [],
468				silent: true,
469			});
470			let stderr = "";
471			let stdout = "";
472			let checkpoint = false;
473			const timer = setTimeout(() => {
474				child.kill("SIGKILL");
475				reject(new TypeError(`D109C_CHILD_TIMEOUT:${edge}:${stdout}:${stderr}`));
476			}, 15_000);
477			child.stdout?.on("data", (chunk: Buffer) => {
478				stdout += chunk.toString();
479			});
480			child.stderr?.on("data", (chunk: Buffer) => {
481				stderr += chunk.toString();
482			});
483			child.on("message", (message: unknown) => {
484				if (
485					typeof message === "object" &&
486					message !== null &&
487					Reflect.get(message, "kind") === "checkpoint" &&
488					Reflect.get(message, "edge") === edge
489				) {
490					checkpoint = true;
491					child.kill("SIGKILL");
492				} else if (typeof message === "object" && message !== null && Reflect.get(message, "kind") === "child-error") {
493					clearTimeout(timer);
494					reject(new TypeError(`D109C_CHILD_ERROR:${edge}:${String(Reflect.get(message, "message"))}`));
495				}
496			});
497			child.on("error", (error) => {
498				clearTimeout(timer);
499				reject(error);
500			});
501			child.on("exit", (_code, signal) => {
502				clearTimeout(timer);
503				if (!checkpoint || signal !== "SIGKILL") {
504					reject(new TypeError(`D109C_CHILD_EXIT_INVALID:${edge}:${String(signal)}:${stdout}:${stderr}`));
505					return;
506				}
507				resolvePromise();
508			});
509		});
510	}
