 91	async function fiveGenerationInput(
 92		store: AheDurableStore,
 93		bytesForIndex: (index: number) => Uint8Array = (index) => Uint8Array.of(index, index + 1, index + 2),
 94		generationCount = 5
 95	): Promise<{
 96		readonly input: Record<string, unknown>;
 97		readonly records: readonly GenerationRecord[];
 98	}> {
 99		let head: ExpectedHead = successful(await store.readHead(D109C_OBJECT), "READ_HEAD");
100		for (let index = 1; index <= generationCount; index += 1) {
101			const generationId = index.toString(16).padStart(64, "0") as GenerationRecord["generationId"];
102			const bytes = bytesForIndex(index);
103			const digest = successful(digestBlob(bytes), "DIGEST_BLOB");
104			const closure = [{ byteLength: bytes.byteLength, digest }];
105			successful(
106				await store.beginGeneration({ baseExpectedHead: head, closure, generationId, objectId: D109C_OBJECT }),
107				"BEGIN"
108			);
109			successful(await store.putCachedBlob({ bytes, digest, generationId, objectId: D109C_OBJECT }), "PUT");
110			successful(await store.promoteReference({ digest, generationId, objectId: D109C_OBJECT }), "PROMOTE");
111			successful(await store.completeGeneration({ generationId, objectId: D109C_OBJECT }), "COMPLETE");
112			head = successful(await store.swapHead({ expectedHead: head, generationId, objectId: D109C_OBJECT }), "SWAP").head;
113		}
114		const records = successful(await store.readGenerationPage({ limit: 16, objectId: D109C_OBJECT }), "PAGE").generations;
115		const byId = new Map(records.map((record) => [record.generationId, record]));
116		if (head.kind !== "present") throw new TypeError("D109C_HEAD_ABSENT");
117		const active = byId.get(head.generationId);
118		const first =
119			active?.baseExpectedHead.kind === "present" ? byId.get(active.baseExpectedHead.generationId) : undefined;
120		const floor = first?.baseExpectedHead.kind === "present" ? byId.get(first.baseExpectedHead.generationId) : undefined;
121		if (active === undefined || first === undefined || floor === undefined) throw new TypeError("D109C_LINEAGE_MISSING");
122		const selected = records
123			.filter(
124				(record) => !new Set([active.generationId, first.generationId, floor.generationId]).has(record.generationId)
125			)
126			.map(({ generationId }) => generationId)
127			.sort();
128		return {
129			input: {
130				activeGenerationId: active.generationId,
131				availabilityPolicyDigest: D109C_POLICY_DIGEST,
132				closedEpoch: 4,
133				expectedHead: head,
134				lineageFloor: {
135					deleteGenerationIds: selected,
136					expectedBaseExpectedHead: floor.baseExpectedHead,
137					generationId: floor.generationId,
138					replacementBaseExpectedHead: { kind: "none", objectId: D109C_OBJECT },
139				},
140				objectId: D109C_OBJECT,
141				rollbackGenerationIds: [first.generationId, floor.generationId],
142			},
143			records,
144		};
145	}
