341					.prepare("INSERT INTO generations(object_id,generation_id,record) VALUES (?,?,?)")
342					.run(D109C_OTHER_OBJECT, d109cGenerationId(9), Uint8Array.of(0));
343			} else if (mutant === "partial-replay") {
344				const floor = generationRecord(database, d109cGenerationId(3));
