346				database
347					.prepare("DELETE FROM promotions WHERE object_id = ? AND generation_id = ?")
348					.run(D109C_OBJECT, first.generationId);
349				database
350					.prepare("DELETE FROM generations WHERE object_id = ? AND generation_id = ?")
351					.run(D109C_OBJECT, first.generationId);
352			}
