434	function reopenedShape(filename: string): ReopenShape {
435		return withDatabase(filename, (database) => {
436			const generations = database
437				.prepare("SELECT generation_id,record FROM generations WHERE object_id = ? ORDER BY generation_id")
438				.all(D109C_OBJECT) as Array<{ readonly generation_id: string; readonly record: Uint8Array }>;
439			const floor = generations.find(({ generation_id }) => generation_id === d109cGenerationId(3));
440			if (floor === undefined) throw new TypeError("D109C_REOPEN_FLOOR_MISSING");
441			const decodedFloor = decodeGenerationRecordV1(floor.record);
442			if (decodedFloor.ok === false) throw new TypeError(`D109C_REOPEN_FLOOR_INVALID:${decodedFloor.reason}`);
443			const active = generations.find(({ generation_id }) => generation_id === d109cGenerationId(5));
444			if (active === undefined) throw new TypeError("D109C_REOPEN_ACTIVE_MISSING");
445			const decodedActive = decodeGenerationRecordV1(active.record);
446			if (decodedActive.ok === false) throw new TypeError(`D109C_REOPEN_ACTIVE_INVALID:${decodedActive.reason}`);
447			return Object.freeze({
448				blobs: Number((database.prepare("SELECT COUNT(*) AS count FROM blobs").get() as { count: number }).count),
449				floorNormalized: decodedFloor.value.baseExpectedHead.kind === "none",
450				generationIds: Object.freeze(generations.map(({ generation_id }) => generation_id)),
451				headGenerationId: decodedActive.value.generationId,
452				integrity: String(
453					(database.prepare("PRAGMA integrity_check").get() as { integrity_check: string }).integrity_check
454				),
455				promotions: Number(
456					(database.prepare("SELECT COUNT(*) AS count FROM promotions").get() as { count: number }).count
457				),
458			});
459		});
460	}
