 1	/* eslint-disable @typescript-eslint/explicit-function-return-type -- Future built maintenance owner is the RED seam. */
 2	const [databaseFilename, target] = process.argv.slice(2);
 3	if (databaseFilename === undefined || target === undefined) {
 4		throw new TypeError("D109C_CHILD_ARGUMENTS_INVALID");
 5	}
 6	
 7	let armed = false;
 8	
 9	function checkpoint(edge) {
10		if (!armed || edge !== target) return;
11		process.send?.({ edge, kind: "checkpoint" });
12		Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0);
13	}
14	
15	function successful(result, label) {
16		if (!result?.ok) throw new TypeError(`D109C_CHILD_${label}:${String(result?.reason)}`);
17		return result.value;
18	}
19	
20	try {
21		const [storage, maintenanceModule, instrumentation] = await Promise.all([
22			import("../../../storage/dist/src/index.js"),
23			import("../../dist/src/maintenance.js"),
24			import("../../dist/src/test-instrumentation.js"),
25		]);
26		const instrumented = instrumentation.createInstrumentedSqliteAheDurableStore({ filename: databaseFilename });
27		instrumentation.installNodeAheReclamationCrashObserver(instrumented.store, checkpoint);
28		const store = instrumented.store;
29		const maintenance = maintenanceModule.resolveNodeAheReclamationMaintenance(store);
30		if (maintenance === undefined) throw new TypeError("D109C_NODE_MAINTENANCE_MISSING");
31		const objectId = `creator:${"a".repeat(32)}`;
32		const records = [];
33		let head = successful(await store.readHead(objectId), "HEAD");
34		for (let index = 1; index <= 5; index += 1) {
35			const generationId = index.toString(16).padStart(64, "0");
36			const bytes = Uint8Array.of(index, index + 1, index + 2);
37			const digest = successful(storage.digestBlob(bytes), "BLOB_DIGEST");
38			const closure = [{ byteLength: bytes.byteLength, digest }];
39			successful(await store.beginGeneration({ baseExpectedHead: head, closure, generationId, objectId }), "BEGIN");
40			successful(await store.putCachedBlob({ bytes, digest, generationId, objectId }), "PUT");
41			successful(await store.promoteReference({ digest, generationId, objectId }), "PROMOTE");
42			successful(await store.completeGeneration({ generationId, objectId }), "COMPLETE");
43			head = successful(await store.swapHead({ expectedHead: head, generationId, objectId }), "SWAP").head;
44			records.push(successful(await store.readGenerationPage({ limit: 16, objectId }), "PAGE").generations.at(-1));
45		}
46		const floor = records[2];
47		if (floor === undefined) throw new TypeError("D109C_CHILD_FLOOR_MISSING");
48		armed = true;
49		const receipt = await maintenance.reclaimClosedEpoch({
50			activeGenerationId: records[4].generationId,
51			availabilityPolicyDigest: "53775c5c1ee01e346f588966d6e7acb876df2bd8b2abcbe2b2591f216f7d4d9b",
52			closedEpoch: 4,
53			expectedHead: head,
54			lineageFloor: {
55				deleteGenerationIds: [records[0].generationId, records[1].generationId].sort(),
56				expectedBaseExpectedHead: floor.baseExpectedHead,
57				generationId: floor.generationId,
58				replacementBaseExpectedHead: { kind: "none", objectId },
59			},
60			objectId,
61			rollbackGenerationIds: [records[3].generationId, floor.generationId],
62		});
63		process.send?.({ kind: "complete", receipt });
64		await store.close();
65	} catch (error) {
66		process.send?.({
67			kind: "child-error",
68			message: error instanceof Error ? (error.stack ?? error.message) : String(error),
69		});
70		process.exitCode = 1;
71	}

