 21	import type { DatabaseSync } from "node:sqlite";
 22	
 23	export type NodeAheReclamationCrashEdge =
 24		| "after-floor-rewrite"
 25		| "after-promotion-delete"
 26		| "after-generation-delete"
 27		| "after-blob-delete"
 28		| "before-commit"
 29		| "after-commit";
 30	
 31	export type NodeAheReclamationCrashObserver = (edge: NodeAheReclamationCrashEdge) => void;
 32	
 33	export type NodeAheReclamationCountFault = "blob delete" | "floor rewrite" | "generation delete" | "promotion delete";
 34	
 35	type Lifecycle = Readonly<{
 36		isClosed(): boolean;
 37		isPoisoned(): boolean;
 38		latchPoison(): void;
 39	}>;
 40	
 41	type Row = Record<string, unknown>;
 42	
 43	const maintenanceByStore = new WeakMap<AheDurableStore, AheReclamationMaintenance>();
 44	const crashObserverByStore = new WeakMap<AheDurableStore, NodeAheReclamationCrashObserver>();
 45	const countFaultByStore = new WeakMap<AheDurableStore, NodeAheReclamationCountFault>();
 46	
 47	function databaseBytes(value: unknown): Uint8Array {
 48		if (!(value instanceof Uint8Array)) throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "row bytes invalid");
 49		return new Uint8Array(value);
 50	}
 51	
 52	function loadSnapshot(connection: DatabaseSync, objectId: string): AheReclamationSnapshot {
 53		const parsedObjectId = parseStorageObjectId(objectId);
 54		if (!parsedObjectId.ok) throw createAheReclamationError("AHE_RECLAMATION_INVALID_ARGUMENT", "object ID invalid");
 55		const objectRow = connection.prepare("SELECT head_record FROM objects WHERE object_id = ?").get(objectId) as
 56			| Row
 57			| undefined;
 58		let head: ExpectedHead = { kind: "none", objectId: parsedObjectId.value };
 59		if (objectRow !== undefined && objectRow.head_record !== null) {
 60			const decoded = decodeHeadRecordV1(databaseBytes(objectRow.head_record));
 61			if (!decoded.ok || decoded.value.objectId !== objectId) {
 62				throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "head row was malformed or misbound");
 63			}
 64			head = decoded.value;
 65		}
 66	
 67		const generations: GenerationRecord[] = [];
 68		for (const row of connection
 69			.prepare("SELECT object_id, generation_id, record FROM generations ORDER BY object_id, generation_id")
 70			.all() as Row[]) {
 71			const decoded = decodeGenerationRecordV1(databaseBytes(row.record));
 72			if (!decoded.ok || decoded.value.objectId !== row.object_id || decoded.value.generationId !== row.generation_id) {
 73				throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "generation row was malformed or misbound");
 74			}
 75			generations.push(decoded.value);
 76		}
 77	
 78		const promotions = (
 79			connection
 80				.prepare("SELECT object_id, generation_id, digest FROM promotions ORDER BY object_id, generation_id, digest")
 81				.all() as Row[]
 82		).map(
 83			(row) =>
 84				({ objectId: row.object_id, generationId: row.generation_id, digest: row.digest }) as AheReclamationPromotion
 85		);
 86		const blobs = [];
 87		for (const row of connection
 88			.prepare(
 89				"SELECT blobs.digest, blobs.bytes FROM blobs " +
 90					"INNER JOIN (SELECT DISTINCT digest FROM promotions) AS referenced ON referenced.digest = blobs.digest " +
 91					"ORDER BY blobs.digest"
 92			)
 93			.all() as Row[]) {
 94			blobs.push({ digest: row.digest, bytes: databaseBytes(row.bytes) });
 95		}
 96		return { blobs, generations, head, promotions } as AheReclamationSnapshot;
 97	}
 98	
 99	function changed(result: { readonly changes: number | bigint }): number {
100		return Number(result.changes);
101	}
102	
103	function expectCount(
104		store: AheDurableStore,
105		actual: number,
106		expected: number,
107		label: NodeAheReclamationCountFault
108	): void {
109		const observed = countFaultByStore.get(store) === label ? actual + 1 : actual;
110		if (observed !== expected) {
111			throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", `${label} count mismatch`);
112		}
113	}
114	
115	class NodeAheReclamationMaintenance implements AheReclamationMaintenance {
116		public constructor(
117			private readonly store: AheDurableStore,
118			private readonly connection: DatabaseSync,
119			private readonly lifecycle: Lifecycle
120		) {}
121	
122		public async reclaimClosedEpoch(input: unknown): Promise<AheReclamationReceipt> {
123			await Promise.resolve();
124			const captured = captureAheReclamationInput(input);
125			if (this.lifecycle.isClosed()) {
126				throw createAheReclamationError("AHE_RECLAMATION_STORE_CLOSED", "store is closed");
127			}
128			if (this.lifecycle.isPoisoned()) {
129				throw createAheReclamationError("AHE_RECLAMATION_STORE_POISONED", "store is poisoned");
130			}
131			let transaction = false;
132			let committed = false;
133			try {
134				this.connection.exec("BEGIN IMMEDIATE");
135				transaction = true;
136				const decision = classifyAheReclamation(captured, loadSnapshot(this.connection, captured.objectId));
137				const observer = crashObserverByStore.get(this.store);
138				if (decision.floor.normalizedThisCall) {
139					expectCount(
140						this.store,
141						changed(
142							this.connection
143								.prepare("UPDATE generations SET record = ? WHERE object_id = ? AND generation_id = ?")
144								.run(
145									encodeGenerationRecordV1(decision.floor.rewrittenGeneration),
146									captured.objectId,
147									captured.lineageFloor.generationId
148								)
149						),
150						1,
151						"floor rewrite"
152					);
153					observer?.("after-floor-rewrite");
154				}
155				let promotionDeletes = 0;
156				const deletePromotion = this.connection.prepare(
157					"DELETE FROM promotions WHERE object_id = ? AND generation_id = ? AND digest = ?"
158				);
159				for (const promotion of decision.deletePromotions) {
160					promotionDeletes += changed(deletePromotion.run(promotion.objectId, promotion.generationId, promotion.digest));
161				}
162				expectCount(this.store, promotionDeletes, decision.deletePromotions.length, "promotion delete");
163				if (decision.floor.normalizedThisCall) observer?.("after-promotion-delete");
164	
165				let generationDeletes = 0;
166				const deleteGeneration = this.connection.prepare(
167					"DELETE FROM generations WHERE object_id = ? AND generation_id = ?"
168				);
169				for (const generationId of decision.deleteGenerationIds) {
170					generationDeletes += changed(deleteGeneration.run(captured.objectId, generationId));
171				}
172				expectCount(this.store, generationDeletes, decision.deleteGenerationIds.length, "generation delete");
173				if (decision.floor.normalizedThisCall) observer?.("after-generation-delete");
174	
175				let blobDeletes = 0;
176				const deleteBlob = this.connection.prepare("DELETE FROM blobs WHERE digest = ?");
177				for (const digest of decision.deleteBlobDigests) blobDeletes += changed(deleteBlob.run(digest));
178				expectCount(this.store, blobDeletes, decision.deleteBlobDigests.length, "blob delete");
179				if (decision.floor.normalizedThisCall) observer?.("after-blob-delete");
180	
181				const post = classifyAheReclamation(captured, loadSnapshot(this.connection, captured.objectId));
182				if (
183					post.floor.normalizedThisCall ||
184					post.deleteGenerationIds.length !== 0 ||
185					post.deletePromotions.length !== 0 ||
186					post.deleteBlobDigests.length !== 0
187				) {
188					throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "post-state was not a complete replay");
189				}
190				observer?.("before-commit");
191				this.connection.exec("COMMIT");
192				transaction = false;
193				committed = true;
194				observer?.("after-commit");
195				return createAheReclamationReceipt(decision);
196			} catch (error) {
197				if (transaction) {
198					try {
199						this.connection.exec("ROLLBACK");
200					} catch {
201						// Preserve the primary classified failure.
202					}
203				}
204				if (error instanceof AheReclamationError) {
205					if (error.code === "AHE_RECLAMATION_CORRUPT") this.lifecycle.latchPoison();
206					throw error;
207				}
208				if (committed)
209					throw createAheReclamationError("AHE_RECLAMATION_SUBSTRATE_FAILURE", "post-commit observer failed", error);
210				throw createAheReclamationError("AHE_RECLAMATION_SUBSTRATE_FAILURE", "SQLite reclamation failed", error);
211			}
212		}
213	}
