 11	
 12	const HEX_64 = /^[0-9a-f]{64}$/u;
 13	const OBJECT_SALT = /^[0-9a-f]{32}$/u;
 14	const GENERATION_STATES = new Set(["Staged", "Complete", "Adopted", "Superseded", "Discarded"]);
 15	
 16	/**
 17	 * Compares canonical ASCII identifiers without locale-dependent collation.
 18	 * @param left - Left identifier.
 19	 * @param right - Right identifier.
 20	 * @returns Their exact code-unit order.
 21	 */
 22	export function compareCanonicalText(left: string, right: string): number {
 23		return left < right ? -1 : left > right ? 1 : 0;
 24	}
 25	
 26	/**
 27	 * Returns whether a byte view is backed by shared memory.
 28	 * @param bytes - Input value.
 29	 * @returns Whether the backing buffer is shared.
 30	 */
 31	export function hasSharedBacking(bytes: Uint8Array): boolean {
 32		return typeof SharedArrayBuffer !== "undefined" && bytes.buffer instanceof SharedArrayBuffer;
 33	}
 34	
 35	/**
 36	 * Compares two byte sequences without retaining either input.
 37	 * @param left - Input value.
 38	 * @param right - Input value.
 39	 * @returns Whether every byte is equal.
 40	 */
 41	export function bytesEqual(left: Uint8Array, right: Uint8Array): boolean {
 42		if (left.byteLength !== right.byteLength) return false;
 43		for (let index = 0; index < left.byteLength; index++) {
 44			if (left[index] !== right[index]) return false;
 45		}
 46		return true;
 47	}
 48	
 49	/**
 50	 * Returns whether a string contains only paired UTF-16 surrogate code units.
 51	 * @param value - Input value.
 52	 * @returns Whether the string is well formed.
 53	 */
 54	export function isWellFormedUtf16(value: string): boolean {
 55		for (let index = 0; index < value.length; index++) {
 56			const unit = value.charCodeAt(index);
