 45		if (!isClosedRecord(value, ["objectId", "generationId", "baseExpectedHead", "closureDigest", "closure", "state"])) {
 46			return undefined;
 47		}
 48		if (
 49			!isStorageObjectId(value.objectId) ||
 50			!isGenerationId(value.generationId) ||
 51			!isClosureDigest(value.closureDigest) ||
 52			typeof value.state !== "string" ||
 53			!GENERATION_STATES.has(value.state)
 54		) {
 55			return undefined;
 56		}
 57		const baseExpectedHead = copyExpectedHead(value.baseExpectedHead, value.objectId);
 58		if (baseExpectedHead === undefined || !isClosedArray(value.closure) || value.closure.length === 0) return undefined;
 59		const closure: GenerationRef[] = [];
 60		for (const item of value.closure) {
 61			const copied = copyGenerationRef(item);
 62			if (copied === undefined) return undefined;
 63			const previous = closure[closure.length - 1];
 64			if (previous !== undefined && compareCanonicalText(previous.digest, copied.digest) >= 0) return undefined;
 65			closure.push(copied);
 66		}
 67		return {
 68			objectId: value.objectId,
 69			generationId: value.generationId,
 70			baseExpectedHead,
 71			closureDigest: value.closureDigest,
 72			closure,
 73			state: value.state as GenerationRecord["state"],
 74		};
 75	}
 76	
 77	/**
 78	 * Compares exact head union arms and fields.
 79	 * @param left - Input value.
 80	 * @param right - Input value.
 81	 * @returns Whether the heads are exactly equal.
 82	 */
 83	export function headsEqual(left: ExpectedHead, right: ExpectedHead): boolean {
 84		if (left.kind !== right.kind || left.objectId !== right.objectId) return false;
 85		return (
 86			left.kind === "none" ||
 87			(right.kind === "present" &&
 88				left.generationId === right.generationId &&
 89				left.revision === right.revision &&
 90				left.closureDigest === right.closureDigest)
 91		);
 92	}
 93	
 94	/**
 95	 * Copies a head already known to be valid.
 96	 * @param value - Input value.
 97	 * @returns A detached head.
 98	 */
 99	export function cloneHead(value: ExpectedHead): ExpectedHead {
100		return value.kind === "none" ? { ...value } : { ...value };
101	}
102	
103	/**
104	 * Deep-copies a generation record without codec round-tripping blob bytes.
105	 * @param value - Input value.
106	 * @returns A detached generation record.
107	 */
108	export function cloneGeneration(value: GenerationRecord): GenerationRecord {
109		return {
110			...value,
111			baseExpectedHead: cloneHead(value.baseExpectedHead),
112			closure: value.closure.map((item) => ({ ...item })),
113		};
114	}

