 29	export type BrowserAheReclamationCrashEdge =
 30		| "after-floor-rewrite"
 31		| "after-promotion-delete"
 32		| "after-generation-delete"
 33		| "after-blob-delete"
 34		| "before-commit"
 35		| "after-commit";
 36	
 37	export type BrowserAheReclamationCrashObserver = (
 38		edge: BrowserAheReclamationCrashEdge,
 39		transaction: IDBTransaction
 40	) => void;
 41	
 42	export type BrowserAheReclamationCountFault =
 43		| "blob delete"
 44		| "floor rewrite"
 45		| "generation delete"
 46		| "promotion delete";
 47	
 48	export type BrowserAheReclamationLifecycle = Readonly<{
 49		acquireRecoveryTurn(): (() => void) | Promise<() => void>;
 50		finishOperation(): void;
 51		isClosed(): boolean;
 52		isPoisoned(): boolean;
 53		latchPoison(reason: "NON_CANONICAL_RECORD"): unknown;
 54		startOperation(): IDBDatabase | undefined;
 55	}>;
 56	
 57	type TransactionOutcome = Readonly<{ ok: true }> | Readonly<{ cause: unknown; ok: false }>;
 58	
 59	const maintenanceByStore = new WeakMap<AheDurableStore, AheReclamationMaintenance>();
 60	const crashObserverByStore = new WeakMap<AheDurableStore, BrowserAheReclamationCrashObserver>();
 61	const countFaultByStore = new WeakMap<AheDurableStore, BrowserAheReclamationCountFault>();
 62	
 63	function rowProperty(value: unknown, key: string): unknown {
 64		if (typeof value !== "object" || value === null) return undefined;
 65		const descriptor = Object.getOwnPropertyDescriptor(value, key);
 66		return descriptor !== undefined && "value" in descriptor ? descriptor.value : undefined;
 67	}
 68	
 69	function bytes(value: unknown): Uint8Array {
 70		if (!(value instanceof Uint8Array)) throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "row bytes invalid");
 71		return new Uint8Array(value);
 72	}
 73	
 74	function requestValue<T>(request: IDBRequest<T>): Promise<T> {
 75		return new Promise((resolve, reject) => {
 76			request.addEventListener("success", () => resolve(request.result), { once: true });
 77			request.addEventListener("error", () => reject(request.error ?? new Error("IndexedDB request failed")), {
 78				once: true,
 79			});
 80		});
 81	}
 82	
 83	function transactionOutcome(transaction: IDBTransaction): Promise<TransactionOutcome> {
 84		return new Promise((resolve) => {
 85			let observedError: unknown;
 86			transaction.addEventListener("complete", () => resolve({ ok: true }), { once: true });
 87			transaction.addEventListener(
 88				"abort",
 89				() => resolve({ cause: transaction.error ?? observedError ?? new Error("transaction aborted"), ok: false }),
 90				{ once: true }
 91			);
 92			transaction.addEventListener(
 93				"error",
 94				() => {
 95					observedError ??= transaction.error ?? new Error("transaction failed");
 96				},
 97				{ once: true }
 98			);
 99		});
100	}
101	
102	function abortIfActive(transaction: IDBTransaction): void {
103		try {
104			transaction.abort();
105		} catch {
106			// Preserve the primary classified failure.
107		}
108	}
109	
110	async function expectKey(
111		store: AheDurableStore,
112		objectStore: IDBObjectStore,
113		key: IDBValidKey,
114		expected: "absent" | "present",
115		label: BrowserAheReclamationCountFault
116	): Promise<void> {
117		const value = await requestValue(objectStore.getKey(key));
118		const matches = expected === "present" ? value !== undefined : value === undefined;
119		if (!matches || countFaultByStore.get(store) === label) {
120			throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", `${label} count mismatch`);
121		}
122	}
123	
124	async function loadSnapshot(transaction: IDBTransaction, objectId: string): Promise<AheReclamationSnapshot> {
125		const parsedObjectId = parseStorageObjectId(objectId);
126		if (!parsedObjectId.ok) throw createAheReclamationError("AHE_RECLAMATION_INVALID_ARGUMENT", "object ID invalid");
127		const objectRow = await requestValue(transaction.objectStore(PHASE_2D_OBJECTS_STORE).get(objectId));
128		let head: ExpectedHead = { kind: "none", objectId: parsedObjectId.value };
129		const headRecord = rowProperty(objectRow, "record");
130		if (objectRow !== undefined && headRecord !== null && headRecord !== undefined) {
131			const decoded = decodeHeadRecordV1(bytes(headRecord));
132			if (!decoded.ok || decoded.value.objectId !== objectId) {
133				throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "head row was malformed or misbound");
134			}
135			head = decoded.value;
136		}
137	
138		const generationRows = await requestValue(transaction.objectStore(PHASE_2D_GENERATIONS_STORE).getAll());
139		const generations: GenerationRecord[] = [];
140		for (const row of generationRows) {
141			const decoded = decodeGenerationRecordV1(bytes(rowProperty(row, "record")));
142			if (
143				!decoded.ok ||
144				decoded.value.objectId !== rowProperty(row, "objectId") ||
145				decoded.value.generationId !== rowProperty(row, "generationId")
146			) {
147				throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "generation row was malformed or misbound");
148			}
149			generations.push(decoded.value);
150		}
151	
152		const promotionRows = await requestValue(transaction.objectStore(PHASE_2D_PROMOTIONS_STORE).getAll());
153		const promotions = promotionRows.map(
154			(row) =>
155				({
156					digest: rowProperty(row, "digest"),
157					generationId: rowProperty(row, "generationId"),
158					objectId: rowProperty(row, "objectId"),
159				}) as AheReclamationPromotion
160		);
161		const digests = [...new Set(promotions.map(({ digest }) => digest))];
162		const blobStore = transaction.objectStore(PHASE_2D_BLOBS_STORE);
163		const blobs = [];
164		for (const digest of digests) {
165			const row = await requestValue(blobStore.get(digest));
166			if (row !== undefined) blobs.push({ bytes: bytes(rowProperty(row, "bytes")), digest });
167		}
168		return { blobs, generations, head, promotions } as AheReclamationSnapshot;
169	}
170	
171	class BrowserAheReclamationMaintenance implements AheReclamationMaintenance {
172		public constructor(
173			private readonly store: AheDurableStore,
174			private readonly lifecycle: BrowserAheReclamationLifecycle
175		) {}
176	
177		public async reclaimClosedEpoch(input: unknown): Promise<AheReclamationReceipt> {
178			const captured = captureAheReclamationInput(input);
179			const database = this.lifecycle.startOperation();
180			if (database === undefined) {
181				throw createAheReclamationError("AHE_RECLAMATION_STORE_CLOSED", "store is closed");
182			}
183			const turn = this.lifecycle.acquireRecoveryTurn();
184			const release = typeof turn === "function" ? turn : await turn;
185			let transaction: IDBTransaction | undefined;
186			let completion: Promise<TransactionOutcome> | undefined;
187			let committed = false;
188			try {
189				if (this.lifecycle.isClosed()) {
190					throw createAheReclamationError("AHE_RECLAMATION_STORE_CLOSED", "store closed before reclamation");
191				}
192				if (this.lifecycle.isPoisoned()) {
193					throw createAheReclamationError("AHE_RECLAMATION_STORE_POISONED", "store is poisoned");
194				}
195				transaction = database.transaction(
196					[PHASE_2D_BLOBS_STORE, PHASE_2D_GENERATIONS_STORE, PHASE_2D_OBJECTS_STORE, PHASE_2D_PROMOTIONS_STORE],
197					"readwrite",
198					{ durability: "strict" }
199				);
200				completion = transactionOutcome(transaction);
201				if (transaction.durability !== "strict") {
202					throw createAheReclamationError("AHE_RECLAMATION_SUBSTRATE_FAILURE", "strict durability unavailable");
203				}
204				const decision = classifyAheReclamation(captured, await loadSnapshot(transaction, captured.objectId));
205				const observer = crashObserverByStore.get(this.store);
206				if (decision.floor.normalizedThisCall) {
207					const generationStore = transaction.objectStore(PHASE_2D_GENERATIONS_STORE);
208					const floorKey = [captured.objectId, captured.lineageFloor.generationId];
209					await expectKey(this.store, generationStore, floorKey, "present", "floor rewrite");
210					await requestValue(
211						generationStore.put({
212							generationId: captured.lineageFloor.generationId,
213							objectId: captured.objectId,
214							record: encodeGenerationRecordV1(decision.floor.rewrittenGeneration),
215						})
216					);
217					await expectKey(this.store, generationStore, floorKey, "present", "floor rewrite");
218					observer?.("after-floor-rewrite", transaction);
219				}
220				const promotionStore = transaction.objectStore(PHASE_2D_PROMOTIONS_STORE);
221				for (const promotion of decision.deletePromotions) {
222					const key = [promotion.objectId, promotion.generationId, promotion.digest];
223					await expectKey(this.store, promotionStore, key, "present", "promotion delete");
224					await requestValue(promotionStore.delete(key));
225					await expectKey(this.store, promotionStore, key, "absent", "promotion delete");
226				}
227				if (decision.floor.normalizedThisCall) observer?.("after-promotion-delete", transaction);
228				const generationStore = transaction.objectStore(PHASE_2D_GENERATIONS_STORE);
229				for (const generationId of decision.deleteGenerationIds) {
230					const key = [captured.objectId, generationId];
231					await expectKey(this.store, generationStore, key, "present", "generation delete");
232					await requestValue(generationStore.delete(key));
233					await expectKey(this.store, generationStore, key, "absent", "generation delete");
234				}
235				if (decision.floor.normalizedThisCall) observer?.("after-generation-delete", transaction);
236				const blobStore = transaction.objectStore(PHASE_2D_BLOBS_STORE);
237				for (const digest of decision.deleteBlobDigests) {
238					await expectKey(this.store, blobStore, digest, "present", "blob delete");
239					await requestValue(blobStore.delete(digest));
240					await expectKey(this.store, blobStore, digest, "absent", "blob delete");
241				}
242				if (decision.floor.normalizedThisCall) observer?.("after-blob-delete", transaction);
243	
244				const post = classifyAheReclamation(captured, await loadSnapshot(transaction, captured.objectId));
245				if (
246					post.floor.normalizedThisCall ||
247					post.deleteGenerationIds.length !== 0 ||
248					post.deletePromotions.length !== 0 ||
249					post.deleteBlobDigests.length !== 0
250				) {
251					throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "post-state was not a complete replay");
252				}
253				observer?.("before-commit", transaction);
254				transaction.commit();
255				const outcome = await completion;
256				if (!outcome.ok) throw outcome.cause;
257				committed = true;
258				observer?.("after-commit", transaction);
259				return createAheReclamationReceipt(decision);
260			} catch (error) {
261				if (!committed && transaction !== undefined) abortIfActive(transaction);
262				if (!committed && completion !== undefined) await completion;
263				if (error instanceof AheReclamationError) {
264					if (error.code === "AHE_RECLAMATION_CORRUPT") this.lifecycle.latchPoison("NON_CANONICAL_RECORD");
265					throw error;
266				}
267				throw createAheReclamationError("AHE_RECLAMATION_SUBSTRATE_FAILURE", "IndexedDB reclamation failed", error);
268			} finally {
269				release();
270				this.lifecycle.finishOperation();
271			}
272		}
273	}
274	
275	/**
276	 * Registers maintenance authority for one genuine IndexedDB facade.
277	 * @param store - Exact facade identity.
278	 * @param lifecycle - Owning facade lifecycle controls.
279	 */
280	export function registerBrowserAheReclamationMaintenance(
281		store: AheDurableStore,
282		lifecycle: BrowserAheReclamationLifecycle
283	): void {
284		maintenanceByStore.set(store, new BrowserAheReclamationMaintenance(store, lifecycle));
285	}
286	
287	/**
288	 * Resolves maintenance only for the registered facade identity.
289	 * @param store - Candidate facade identity.
290	 * @returns The identity-bound maintenance owner, if registered.
291	 */
292	export function browserAheReclamationMaintenanceForStore(
293		store: AheDurableStore
294	): AheReclamationMaintenance | undefined {
295		return maintenanceByStore.get(store);
296	}
297	
298	/**
299	 * Installs the maintenance-only worker-termination observer for a package-local test.
300	 * @param store - Exact registered IndexedDB facade.
301	 * @param observer - Fixed checkpoint observer.
302	 */
303	export function installBrowserAheReclamationCrashObserver(
304		store: AheDurableStore,
305		observer: BrowserAheReclamationCrashObserver
306	): void {
307		if (!maintenanceByStore.has(store)) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
308		crashObserverByStore.set(store, observer);
309	}
310	
311	/**
312	 * Installs one fixed maintenance-only count mismatch for a package-local browser test.
313	 * @param store - Exact registered IndexedDB facade.
314	 * @param fault - Fixed row-count category to misreport.
315	 */
316	export function installBrowserAheReclamationCountFault(
317		store: AheDurableStore,
318		fault: BrowserAheReclamationCountFault
319	): void {
320		if (!maintenanceByStore.has(store)) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
321		countFaultByStore.set(store, fault);
322	}

