 1	/* eslint-disable import/no-unresolved -- Focused build plugin owns the causal maintenance alias. */
 2	import { digestBlob, type ExpectedHead, type GenerationRecord } from "@ts-drp/storage";
 3	
 4	import {
 5		D109C_BROWSER_MAINTENANCE_READY,
 6		resolveBrowserAheReclamationMaintenance,
 7	} from "#phase-6b-ahe-reclamation-maintenance";
 8	import { createBrowserAheDurableStore } from "../../src/index.js";
 9	import { installBrowserAheReclamationCrashObserver } from "../../src/internal/ahe-reclamation.js";
10	
11	const EDGES = Object.freeze([
12		"after-floor-rewrite",
13		"after-promotion-delete",
14		"after-generation-delete",
15		"after-blob-delete",
16		"before-commit",
17		"after-commit",
18	]);
19	const OBJECT_ID = `creator:${"a".repeat(32)}`;
20	const POLICY_DIGEST = "53775c5c1ee01e346f588966d6e7acb876df2bd8b2abcbe2b2591f216f7d4d9b";
21	
22	function successful<T>(result: { ok: false; reason: string } | { ok: true; value: T }, label: string): T {
23		if (result.ok === false) throw new TypeError(`D109C_BROWSER_WORKER_${label}:${result.reason}`);
24		return result.value;
25	}
26	
27	async function run(databaseName: string, edge: string): Promise<void> {
28		const store = await createBrowserAheDurableStore({ databaseName });
29		const maintenance = resolveBrowserAheReclamationMaintenance(store);
30		if (maintenance === undefined) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
31		let head: ExpectedHead = successful(await store.readHead(OBJECT_ID), "HEAD");
32		const records: GenerationRecord[] = [];
33		for (let index = 1; index <= 5; index += 1) {
34			const generationId = index.toString(16).padStart(64, "0");
35			const bytes = Uint8Array.of(index, index + 1, index + 2);
36			const digest = successful(digestBlob(bytes), "DIGEST");
37			const closure = [{ byteLength: bytes.byteLength, digest }];
38			successful(
39				await store.beginGeneration({ baseExpectedHead: head, closure, generationId, objectId: OBJECT_ID }),
40				"BEGIN"
41			);
42			successful(await store.putCachedBlob({ bytes, digest, generationId, objectId: OBJECT_ID }), "PUT");
43			successful(await store.promoteReference({ digest, generationId, objectId: OBJECT_ID }), "PROMOTE");
44			successful(await store.completeGeneration({ generationId, objectId: OBJECT_ID }), "COMPLETE");
45			head = successful(await store.swapHead({ expectedHead: head, generationId, objectId: OBJECT_ID }), "SWAP").head;
46		}
47		records.push(...successful(await store.readGenerationPage({ limit: 16, objectId: OBJECT_ID }), "PAGE").generations);
48		const floor = records[2];
49		const first = records[3];
50		const active = records[4];
51		const olderFirst = records[0];
52		const olderSecond = records[1];
53		if (
54			olderFirst === undefined ||
55			olderSecond === undefined ||
56			floor === undefined ||
57			first === undefined ||
58			active === undefined ||
59			head.kind !== "present"
60		) {
61			throw new TypeError("D109C_BROWSER_WORKER_LINEAGE_MISSING");
62		}
63		installBrowserAheReclamationCrashObserver(store, (observed) => {
64			if (observed !== edge) return;
65			self.postMessage({ edge, kind: "checkpoint" });
66			Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0);
67		});
68		await maintenance.reclaimClosedEpoch({
69			activeGenerationId: active.generationId,
70			availabilityPolicyDigest: POLICY_DIGEST,
71			closedEpoch: 4,
72			expectedHead: head,
73			lineageFloor: {
74				deleteGenerationIds: [olderFirst.generationId, olderSecond.generationId].sort(),
75				expectedBaseExpectedHead: floor.baseExpectedHead,
76				generationId: floor.generationId,
77				replacementBaseExpectedHead: { kind: "none", objectId: OBJECT_ID },
78			},
79			objectId: OBJECT_ID,
80			rollbackGenerationIds: [first.generationId, floor.generationId],
81		});
82		throw new TypeError(`D109C_BROWSER_WORKER_CHECKPOINT_MISSED:${edge}`);
83	}
84	
85	self.addEventListener("message", (event: MessageEvent<{ readonly databaseName?: string; readonly edge?: string }>) => {
86		const { databaseName, edge } = event.data;
87		if (!D109C_BROWSER_MAINTENANCE_READY || databaseName === undefined || edge === undefined || !EDGES.includes(edge)) {
88			self.postMessage({ kind: "refused", ready: D109C_BROWSER_MAINTENANCE_READY });
89			return;
90		}
91		void run(databaseName, edge).catch((error: unknown) => {
92			self.postMessage({
93				kind: "worker-error",
94				message: error instanceof Error ? (error.stack ?? error.message) : String(error),
95			});
96		});
97	});
98	
99	self.postMessage({ kind: "ready", ready: D109C_BROWSER_MAINTENANCE_READY });

