1	/* eslint-disable import/no-unresolved -- Focused build plugin owns the causal maintenance alias. */
2	import {
3		type AheDurableStore,
4		createMemoryAheDurableStore,
5		decodeGenerationRecordV1,
6		decodeHeadRecordV1,
7		digestBlob,
8		encodeGenerationRecordV1,
9		type ExpectedHead,
10		type GenerationRecord,
11	} from "@ts-drp/storage";
12	
13	import {
14		D109C_BROWSER_MAINTENANCE_READY,
15		resolveBrowserAheReclamationMaintenance,
16	} from "#phase-6b-ahe-reclamation-maintenance";
17	import { createBrowserAheDurableStore } from "../../src/index.js";
18	import { installBrowserAheReclamationCountFault } from "../../src/internal/ahe-reclamation.js";
19	import {
20		PHASE_2D_BLOBS_STORE,
21		PHASE_2D_GENERATIONS_STORE,
22		PHASE_2D_OBJECTS_STORE,
23		PHASE_2D_PROMOTIONS_STORE,
24	} from "../../src/internal/schema-idb.js";
25	
26	const OBJECT_ID = `creator:${"a".repeat(32)}`;
27	const OTHER_OBJECT_ID = `creator:${"b".repeat(32)}`;
28	const POLICY_DIGEST = "53775c5c1ee01e346f588966d6e7acb876df2bd8b2abcbe2b2591f216f7d4d9b";
29	const LINEAGE_MUTANTS = Object.freeze([
30		"head-different",
31		"revision-stale",
32		"active-mismatch",
33		"rollback-insufficient",
34		"rollback-wrong-countable-pair",
35		"identity-duplicate",
36		"closure-changed",
37		"state-changed",
38		"floor-wrong",
39		"former-parent-wrong",
40		"lineage-gap",
41		"lineage-cycle",
42		"surviving-branch",
43		"extra-target-row",
44		"post-state-dangling-parent",
45	] as const);
46	const CORRUPTION_MUTANTS = Object.freeze([
47		"retained-blob-missing",
48		"retained-blob-corrupt",
49		"promotion-missing",
50		"promotion-extra",
51		"promotion-wrong-digest",
52		"target-generation-malformed",
53		"unrelated-generation-malformed",
54		"generation-key-record-mismatch",
55		"partial-replay",
56	] as const);
57	const COUNT_MUTANTS = Object.freeze([
58		"floor-update-count",
59		"promotion-delete-count",
60		"generation-delete-count",
61		"blob-delete-count",
62	] as const);
63	const REFERENCE_CASES = Object.freeze([
64		"retained-shared-blob",
65		"cross-object-shared-blob",
66		"candidate-only-blob",
67		"unrelated-orphan-retained",
68		"staged-partial-promotions",
69		"discarded-partial-promotions",
70	] as const);
