76	function noHead(objectId = OBJECT_ID): ExpectedHead {
77		return { kind: "none", objectId };
78	}
79	
80	function successful<T>(result: { ok: false; reason: string } | { ok: true; value: T }, label: string): T {
81		if (result.ok === false) throw new TypeError(`D109C_BROWSER_${label}:${result.reason}`);
82		return result.value;
83	}
84	
85	async function failureCode(promise: Promise<unknown>): Promise<string | undefined> {
86		try {
87			await promise;
88			return undefined;
