const AHE_STORES = [
	PHASE_2D_BLOBS_STORE,
	PHASE_2D_GENERATIONS_STORE,
	PHASE_2D_OBJECTS_STORE,
	PHASE_2D_PROMOTIONS_STORE,
] as const;

async function withRawDatabase<T>(
	databaseName: string,
	mode: IDBTransactionMode,
	runTransaction: (transaction: IDBTransaction) => Promise<T>
