529	async function runMutantMatrix(prefix: string): Promise<Record<string, unknown>> {
530		const cases = [...LINEAGE_MUTANTS, ...CORRUPTION_MUTANTS, ...COUNT_MUTANTS];
531		const results: Array<Readonly<{ code: string; mutant: string; poisoned: boolean }>> = [];
532		for (const mutant of cases) {
533			const databaseName = `${prefix}-${mutant}`;
534			const store = await createBrowserAheDurableStore({ databaseName });
535			const maintenance = resolveBrowserAheReclamationMaintenance(store);
536			if (maintenance === undefined) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
537			try {
538				const { input } = await fiveGenerations(store);
539				let request = mutableRequest(input);
540				let expectedCode = "AHE_RECLAMATION_CORRUPT";
541				if ((COUNT_MUTANTS as readonly string[]).includes(mutant)) {
542					installBrowserAheReclamationCountFault(store, countFault(mutant));
543				} else {
544					({ code: expectedCode, request } = await applyMutant(databaseName, input, mutant));
545				}
546				const before = await databaseImage(databaseName);
547				let error: unknown;
548				try {
549					await maintenance.reclaimClosedEpoch(request);
550				} catch (candidate) {
551					error = candidate;
552				}
553				const code =
554					typeof error === "object" && error !== null && typeof Reflect.get(error, "code") === "string"
555						? String(Reflect.get(error, "code"))
556						: undefined;
557				if (code !== expectedCode || !Object.isFrozen(error)) {
558					throw new TypeError(`D109C_BROWSER_MUTANT_CODE:${mutant}:${String(code)}:${expectedCode}`);
559				}
560				if ((await databaseImage(databaseName)) !== before) {
561					throw new TypeError(`D109C_BROWSER_MUTANT_COMMITTED:${mutant}`);
562				}
563				const ordinary = await store.readHead(OBJECT_ID);
564				const poisoned = ordinary.ok === false && ordinary.reason === "STORE_POISONED";
565				if (expectedCode === "AHE_RECLAMATION_CORRUPT" ? !poisoned : ordinary.ok === false) {
566					throw new TypeError(`D109C_BROWSER_MUTANT_LIFECYCLE:${mutant}`);
567				}
568				results.push(Object.freeze({ code: expectedCode, mutant, poisoned }));
569			} finally {
570				await store.close();
571			}
572		}
573		return Object.freeze({ cases: Object.freeze(results), total: results.length });
574	}
