		const input = module.captureAheReclamationInput(mutable);
		expect(Object.keys(input).sort()).toEqual([
			"activeGenerationId",
			"availabilityPolicyDigest",
			"closedEpoch",
			"expectedHead",
			"lineageFloor",
			"objectId",
			"rollbackGenerationIds",
		]);
